def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    opp = [h[1] for h in history]
    my = [h[0] for h in history]
    last_opp = opp[-1]
    last_my = my[-1]

    def streak(seq, ch):
        s = 0
        for x in reversed(seq):
            if x == ch:
                s += 1
            else:
                break
        return s

    opp_d_streak = streak(opp, 'D')
    opp_c_streak = streak(opp, 'C')
    my_d_streak = streak(my, 'D')

    recent_len = 10 if n >= 10 else n
    recent_opp_d = sum(1 for i in range(n - recent_len, n) if opp[i] == 'D')
    recent_opp_c = recent_len - recent_opp_d

    opp_d_total = sum(1 for a in opp if a == 'D')

    if n >= 96:
        if opp_d_streak >= 2 or opp_d_total * 2 >= n:
            return 'D'
        return 'D'

    if opp_d_streak >= 3:
        if rng.random() < 0.08:
            return 'C'
        return 'D'

    if opp_d_streak == 2:
        if last_my == 'D':
            if rng.random() < 0.25:
                return 'C'
            return 'D'
        return 'D'

    if opp_d_streak == 1:
        if last_my == 'D':
            if opp_c_streak == 0 and rng.random() < 0.15:
                return 'C'
            return 'D'
        return 'D'

    if n >= 6:
        early_hard = sum(1 for i in range(min(4, n)) if opp[i] == 'D')
        if early_hard >= 3 and opp_d_total * 2 >= n:
            return 'D'

    if n >= 8 and recent_opp_d >= 5:
        return 'D'

    if last_opp == 'C':
        if opp_d_total == 0 and n >= 4:
            if rng.random() < 0.35:
                return 'D'
            return 'C'
        if opp_d_total * 5 >= n:
            if rng.random() < 0.35:
                return 'D'
            return 'C'
        if recent_opp_d >= 2:
            if rng.random() < 0.1:
                return 'D'
            return 'C'
        if n >= 45 and rng.random() < 0.06:
            return 'D'
        return 'C'

    return 'C'
